<template><SilkRoadWorkspace title="营销数据分析"><section class="head"><div><span>MARKETING ANALYTICS</span><h1>数据分析中心</h1><p>跟踪内容生产、市场分布、视频表现和 AI 优化建议。</p></div><el-button :loading="loading" @click="load">刷新数据</el-button></section><el-alert title="当前指标基于平台内项目、素材、成片与分发记录；广告消耗和店铺成交需接入渠道数据后展示。" type="info" :closable="false" show-icon/><div v-loading="loading"><section class="metrics"><article v-for="item in data?.metricCards||[]" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.trend }}</small></article></section><section class="panels"><article><h2>市场分布</h2><div v-for="item in data?.marketShare||[]" :key="item.name" class="share"><span>{{ item.name }}</span><el-progress :percentage="Number(String(item.value).replace('%',''))||0" /></div><el-empty v-if="!data?.marketShare?.length" description="暂无市场数据" :image-size="70" /></article><article><h2>AI 智能洞察</h2><div v-for="item in data?.insights||[]" :key="item.title" class="insight"><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div><el-empty v-if="!data?.insights?.length" description="生成并分发内容后显示洞察" :image-size="70" /></article></section><section class="recommendations"><h2>优化建议</h2><div><article v-for="item in data?.recommendations||[]" :key="item.title"><strong>{{ item.title }}</strong><p>{{ item.description }}</p></article></div></section></div></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{analyticsAPI}from'@/api/analytics';import type{AnalyticsSummary}from'@/types/analytics';const data=ref<AnalyticsSummary>(),loading=ref(false);const load=async()=>{loading.value=true;try{data.value=await analyticsAPI.summary()}finally{loading.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:22px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p,.insight p,.recommendations p{color:var(--text-secondary)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.metrics article,.panels>article,.recommendations{padding:21px;border:1px solid var(--border-primary);border-radius:18px;background:var(--bg-card)}.metrics span,.metrics small{display:block;color:var(--text-muted)}.metrics strong{display:block;font-size:30px;margin:10px 0}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panels h2,.recommendations h2{margin-bottom:18px}.share{display:grid;grid-template-columns:120px 1fr;align-items:center;margin:12px 0}.insight{padding:13px;background:var(--bg-muted);border-radius:12px;margin:10px 0}.insight p{margin-top:5px}.recommendations{margin-top:18px}.recommendations>div{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.recommendations article{padding:15px;background:var(--bg-muted);border-radius:12px}.recommendations p{margin-top:7px}@media(max-width:800px){.metrics{grid-template-columns:repeat(2,1fr)}.panels{grid-template-columns:1fr}.recommendations>div{grid-template-columns:1fr}}</style>
